<?phprequire_once('common_api_header.php');require_once('../admin/controllers/common_controllers.php');require_once('../admin/booking/controller/booking_controller.php');$data_raw = file_get_contents('php://input');$data = json_decode($data_raw,true);$response = array();function getCityAssignedHomeServicesTickets($conn,$data){	$EmployeeID = $data['EmployeeID'];	// Get City from Employee ID	$where = " where CityLead = $EmployeeID";	$cities_array =  _getTableRecords($conn,'citydata', $where);	$city_name_array = array();	foreach($cities_array as $city)	{		array_push($city_name_array,$city['CityName']);	}	// Get branches in that city 	$quoted_city_name_array = array_map(function($value) {	  return "'" . $value . "'";	}, $city_name_array);	$city_in_query = '(' . implode(',', $quoted_city_name_array) . ')';	$where = " where City_name IN $city_in_query ORDER BY ID DESC";	//echo $where;	$response['data'] = _getTableRecords($conn,'confirm_booking', $where);	$response['error'] = false;	$response['message'] = "Tickets fetched";	return $response;}if(isset($data['EmployeeID'])){	$conn = _connectodb();	$response = getCityAssignedHomeServicesTickets($conn,$data);}else{	$response["error"] = true;	$response["message"] = "Missing User Fields";}echo json_encode($response);?>